export type PanelTheme = 'followVSCode' | 'light' | 'dark';
export type PanelThemeKind = 'light' | 'dark';

export function effectivePanelTheme(theme: PanelTheme, kind: PanelThemeKind): PanelThemeKind {
  return theme === 'followVSCode' ? kind : theme;
}

export function oppositePanelTheme(theme: PanelTheme, kind: PanelThemeKind): PanelThemeKind {
  return effectivePanelTheme(theme, kind) === 'light' ? 'dark' : 'light';
}

// 2026-10-10: owner set text box and dropdown outlines to match the settings dividers (1px, the divider's
// widget border color). Toggle switches keep the earlier #BDBDBD and #85898C, picked by VS Code's body class
// in follow mode; high-contrast themes keep the host's description color for toggles.
export const PANEL_THEME_CSS = ':root { --kren-brand-background: rgb(255, 255, 255); --kren-field-border: var(--vscode-widget-border, var(--vscode-panel-border)); --kren-toggle-border: var(--vscode-descriptionForeground); }\n' +
  ':root:not([data-kren-theme]) body.vscode-light { --kren-toggle-border: rgb(189, 189, 189); }\n' +
  ':root:not([data-kren-theme]) body.vscode-dark { --kren-toggle-border: rgb(133, 137, 140); }\n' + Object.entries(PANEL_PALETTES).map(([kind, values]) =>
  ':root[data-kren-theme="' + kind + '"] { color-scheme: ' + kind + ' !important;\n' +
  Object.entries(values).map(([key, value]) => key + ': ' + value + ' !important;').join('\n') + '\n}'
).join('\n');
